(() => { const s = JSON.parse(localStorage.getItem('toyz-layr:state') || '{}');
 const out = { projects: (s.projects || []).map(p => { const q = { ...p }; return q; }), notes: (s.notes || []).map(n => ({ id: n.id, text: n.text, projectId: n.projectId, layer: n.layer, order: n.order, pinned: n.pinned })) };
 let pre = document.getElementById('__dump'); if (!pre) { pre = document.createElement('pre'); pre.id = '__dump'; pre.style.cssText = 'position:fixed;left:0;top:0;width:1px;height:1px;overflow:hidden;opacity:0;white-space:pre;'; document.body.appendChild(pre); }
 pre.textContent = JSON.stringify(out); })()

